#!/usr/bin/env bash
# aaxis-oro:managed-pre-commit
# Managed by the aaxis-oro plugin: static/quality checks mirrored from this project's CI and tool configs.
# Do not edit; local edits are overwritten. Regenerate: aaxis-oro setup sync --project "$(git rev-parse --show-toplevel)"
# Status: aaxis-oro setup status. Settings: "precommit" in .oro-ai/config.json (path-prefix, atlas, skip), "lint" (phpcs-standard).
# Env: AAXIS_ORO_PRECOMMIT_ALL=1 runs every step regardless of the staged file types (nothing staged also runs all).
# Sources: @@SOURCES@@
set -o pipefail

cd "$(git rev-parse --show-toplevel)" || exit 1

fail=0
# quotepath=off keeps non-ASCII paths literal; quoted ("src/th\303\251.js") they would defeat every gate's ERE.
STAGED="$(git -c core.quotepath=off diff --cached --name-only --diff-filter=ACMRD)"

# GATE (ERE, set per call) limits a step to commits that stage a matching file; unset, or nothing staged, runs it.
run_step() {
    local name="$1"
    shift
    if [[ -n "${GATE:-}" && -n "$STAGED" && -z "${AAXIS_ORO_PRECOMMIT_ALL:-}" ]] && ! grep -Eq -- "$GATE" <<<"$STAGED"; then
        echo "--- ${name} skipped (no staged file of its type)"
        return 0
    fi
    echo "==> ${name}"
    if ! "$@"; then
        echo "xxx ${name} FAILED" >&2
        fail=1
    fi
}

@@IGNORE_LIB@@

# ESLint takes the shared exclusion list as quoted --ignore-pattern arguments (an array, never shell-expanded).
ESLINT_IGN=()
if ! IGNORES="$(read_ignores)"; then
    echo "!!! ${IGNORE_FILE} has unsupported lines (listed above); nothing was linted. Fix them and commit again." >&2
    exit 1
fi
while IFS= read -r entry; do
    [[ -n "$entry" ]] && ESLINT_IGN+=(--ignore-pattern "$entry")
done <<<"$IGNORES"

# ESLint lints only the staged files its full scan would cover: paths under the target that match the
# extension filter (the command's --ext list, else ESLint's directory default). The full target still runs
# when a lint config file is staged, AAXIS_ORO_PRECOMMIT_ALL=1 is set, or nothing is staged -- a config
# change can alter every file's result. Staged files of other types (a .ts in a .js-only setup) lint
# nothing and pass instead of triggering a whole-tree scan.
run_eslint() {
    local files_ere="$1" cfg_ere="$2" target="$3" scope f files=()
    shift 3
    if [[ -n "$STAGED" && -z "${AAXIS_ORO_PRECOMMIT_ALL:-}" ]] && ! grep -Eq -- "$cfg_ere" <<<"$STAGED"; then
        scope="${target#./}"
        scope="${scope%/}"
        while IFS= read -r f; do
            if [[ -z "$scope" || "$scope" == "." || "$f" == "$scope" || "$f" == "$scope/"* ]]; then
                files+=("$f")
            fi
        done < <(git -c core.quotepath=off diff --cached --name-only --diff-filter=ACMR | grep -E -- "$files_ere")
        if [[ ${#files[@]} -gt 0 ]]; then
            "$@" "${files[@]}"
            return
        fi
        echo "--- ESLint: skipped (no staged file it covers)"
        return 0
    fi
    "$@" "$target"
}

# The generated CI lint script (PHPCS/PHPMD); a missing one is a hard failure, never a silent skip.
run_lint_php() {
    local script="$1"
    shift
    if [[ ! -f "$script" ]]; then
        echo "!!! ${script} is missing. It is generated by the aaxis-oro plugin and tracked in the repo: merge the branch that adds it, or run: aaxis-oro setup sync" >&2
        return 1
    fi
    bash "$script" "$@"
}

# Directory arguments are replaced by the tracked YAML files under them (CI sees the tracked tree only; yamllint has no ignore flag).
run_yamllint() {
    local args=() files=() arg file dirs=0
    for arg in "$@"; do
        if [[ -d "$arg" ]]; then
            dirs=1
            while IFS= read -r -d '' file; do
                files+=("$file")
            done < <(git ls-files -z -- "$arg" | grep -zE '\.ya?ml$')
        else
            args+=("$arg")
        fi
    done
    if [[ "$dirs" -eq 1 && ${#files[@]} -eq 0 ]]; then
        return 0
    fi
    if command -v yamllint >/dev/null 2>&1; then
        yamllint "${args[@]}" "${files[@]}"
    elif command -v docker >/dev/null 2>&1; then
        # The image's entrypoint is yamllint itself; do not repeat the binary name.
        docker run --rm -v "$PWD":/data -w /data cytopia/yamllint:latest "${args[@]}" "${files[@]}"
    else
        echo "!!! yamllint unavailable (no yamllint, no docker); fix: aaxis-oro setup sync" >&2
        return 1
    fi
}

# Doctrine schema drift against the LOCAL database (prod kernel); never the test stack.
run_schema_drift() {
    case "${ORO_ENV:-${APP_ENV:-}}" in
        test|behat_test) echo "refusing: ORO_ENV/APP_ENV points at the test stack; the drift check measures the local database" >&2; return 1 ;;
    esac
    case "${ORO_DB_URL:-}${ORO_DB_DSN:-}" in
        *oro_test*) echo "refusing: the database DSN points at the test stack (oro_test*)" >&2; return 1 ;;
    esac
    local out err rc sql
    err="$(mktemp)"
    out="$(ORO_ENV=prod APP_ENV=prod php bin/console doctrine:schema:update --dump-sql --env=prod --no-debug 2>"$err")"
    rc=$?
    if [[ "$rc" -ne 0 ]]; then
        cat "$err" >&2
        rm -f "$err"
        echo "!!! schema drift check could not run (console exit $rc); this is not a pass. Fix the local stack, or opt out with \"skip\": [\"schema-drift\"] under \"precommit\" in .oro-ai/config.json" >&2
        return 1
    fi
    rm -f "$err"
    # Blank lines, SQL comments and the "[OK] Nothing to update" banner are not drift.
    sql="$(grep -Ev '^[[:space:]]*$|^[[:space:]]*--|Nothing to update|^[[:space:]]*\[(OK|NOTE)\]' <<<"$out")"
    if [[ -z "$sql" ]]; then
        return 0
    fi
    if [[ "$(grep -c 'ADD CONSTRAINT' <<<"$sql")" -ge 50 ]]; then
        echo "database looks incomplete (hundreds of ADD CONSTRAINT lines): an install or migration is probably still running against the local database. Wait for it to finish and commit again; do not use --no-verify." >&2
    else
        echo "Doctrine schema drift detected:" >&2
        echo "$sql" >&2
        echo "See solutions/references/entities/entity-extend-indexes.md (entity_extend.yml) for DROP INDEX on extend fields." >&2
    fi
    return 1
}
@@NODE@@
@@STEPS@@

if [[ "$fail" -ne 0 ]]; then
    echo "" >&2
    echo "pre-commit checks failed -- fix the issues above before committing." >&2
    exit 1
fi
exit 0
